<script setup>
import {ref,computed,watch} from 'vue';
import {api,scope,state,company,can,useResource,changed,notify,ask} from '../lib/workspace';
import BaseModal from './BaseModal.vue';
import {dateTime} from '../lib/format';
const props=defineProps({date:{type:String,required:true}});
const preview=ref(null),bundle=ref(null),busy=ref(false),error=ref(''),query=ref(''),page=ref(1),detail=ref(null),savedId=ref(null),savedRows=ref({rows:[],total:0}),result=ref(null);
let sequence=0,readSequence=0;
const {data:loads,reload}=useResource(()=>api(scope('/cfop-source-loads')));
const filtered=computed(()=>(preview.value?.rows||[]).filter(r=>!query.value||(r.code+' '+r.source_description).toLocaleLowerCase().includes(query.value.toLocaleLowerCase())));
const total=computed(()=>savedId.value?savedRows.value.total:filtered.value.length);
const visible=computed(()=>savedId.value?savedRows.value.rows:filtered.value.slice((page.value-1)*50,page.value*50));
const pages=computed(()=>Math.max(1,Math.ceil(total.value/50)));
const labels={revenue:'Faturamento',revenue_tax_base:'Composição · base de cálculo',revenue_exempt:'Composição · isentas',revenue_other:'Composição · outras',icms_declared:'Tributa ICMS · indicador da origem',ipi_declared:'Tributa IPI · indicador da origem',gi_declared:'Entra para GI · indicador da origem',me_epp_purchases:'Enquadramento ME/EPP por compras'};
async function prepare(){const n=++sequence,cid=state.companyId;busy.value=true;error.value='';savedId.value=null;try{const r=await api(scope('/cfop-source-loads/preview',cid),{method:'POST',body:{date:props.date,...(bundle.value?{bundle:bundle.value}:{})}});if(n===sequence&&cid===state.companyId)preview.value=r;}catch(e){if(n===sequence)error.value=e.message;}finally{if(n===sequence)busy.value=false;}}
watch(()=>[state.companyId,props.date],()=>{sequence++;readSequence++;preview.value=null;bundle.value=null;savedId.value=null;result.value=null;detail.value=null;page.value=1;query.value='';prepare()},{immediate:true});
watch(query,()=>{page.value=1});
async function readSaved(){if(!savedId.value)return;const n=++readSequence,cid=state.companyId,id=savedId.value;try{const r=await api(scope(`/cfop-source-loads/${id}/rows?`+new URLSearchParams({search:query.value,page:String(page.value)}),cid));if(n===readSequence&&cid===state.companyId&&id===savedId.value)savedRows.value=r;}catch(e){if(n===readSequence)error.value=e.message;}}
watch([savedId,page,query],readSaved);
async function choose(event){const file=event.target.files[0];if(!file)return;if(file.size>10*1024*1024){error.value='A carga deve ter até 10 MB.';return;}const n=++sequence;preview.value=null;savedId.value=null;busy.value=true;try{const data=JSON.parse(await file.text());if(n!==sequence)return;bundle.value=data;result.value=null;page.value=1;await prepare();}catch(e){if(n===sequence)error.value='Não foi possível ler a carga JSON: '+e.message;}finally{event.target.value='';if(n===sequence)busy.value=false;}}
async function standard(){bundle.value=null;result.value=null;page.value=1;query.value='';await prepare();}
async function apply(){const p=preview.value,cid=state.companyId,n=sequence,selected=bundle.value,date=props.date;const reason=await ask({title:'Importar carga CFOP na empresa?',message:`${company.value.name}: preservar ${p.record_count} registros da origem e completar a tabela com ${p.official_catalog_count} CFOPs da referência CONFAZ, mantendo os cadastros existentes. Indicadores e alíquotas ficarão sem aplicação automática.`,inputLabel:'Motivo da carga',required:true,confirmLabel:'Importar carga'});if(!reason||n!==sequence||cid!==state.companyId||date!==props.date)return;busy.value=true;error.value='';try{const r=await api(scope('/cfop-source-loads',cid),{method:'POST',body:{date,reason,preview_hash:p.preview_hash,...(selected?{bundle:selected}:{})}});if(n!==sequence||cid!==state.companyId)return;result.value=r;notify(r.duplicate?'Carga já preservada nesta empresa.':`${r.record_count} registros preservados; ${r.created} CFOPs cadastrados.`);changed();await reload();await prepare();}catch(e){if(n===sequence)error.value=e.message;}finally{if(n===sequence)busy.value=false;}}
function inspectLoad(id){savedRows.value={rows:[],total:0};page.value=1;query.value='';savedId.value=id;detail.value=null;}
</script>
<template><div class="panel cfop-source-panel">
<div class="source-actions"><button class="button" :disabled="busy" @click="standard">Carga padrão enviada</button><label class="button">Selecionar carga JSON<input type="file" accept=".json" :disabled="busy" style="display:none" aria-label="Selecionar carga CFOP JSON" @change="choose"/></label><a class="button" :href="'/api'+scope('/cfop-source-loads/default')" download>Baixar carga padrão</a></div>
<p>Descrições, indicadores e alíquotas dos relatórios são referências da origem. A importação preserva esses dados sem criar regras tributárias ou converter códigos antigos.</p>
<p v-if="error" class="message error" role="alert">{{error}}</p>
<template v-if="preview&&!savedId"><div class="summary-strip"><div><strong>{{preview.record_count}}</strong><span>registros da origem</span></div><div><strong>{{preview.official}}</strong><span>coincidem com a referência</span></div><div><strong>{{preview.legacy}}</strong><span>códigos de 3 dígitos</span></div><div><strong>{{preview.unmatched}}</strong><span>sem correspondência</span></div></div><p>{{preview.pdf_pages}} páginas do PDF · {{preview.official_absent_from_sources.length}} CFOPs oficiais ausentes nos anexos são mantidos pela referência CONFAZ · {{preview.without_rates}} registros sem alíquotas informadas.</p><p>{{preview.catalogs_create}} CFOPs oficiais a cadastrar · {{preview.catalogs_preserve}} existentes a preservar. A origem não informou vigência dos parâmetros.</p><button v-if="can('fiscal.masters','create')" class="button primary" :disabled="busy||preview.already_imported" @click="apply">{{preview.already_imported?'Carga já importada nesta empresa':'Importar carga na empresa'}}</button></template>
<p v-if="result" class="message success">{{result.record_count}} registros de origem preservados. Nenhuma regra ou alíquota foi ativada.</p>
<label v-if="loads.length">Cargas preservadas nesta empresa<select aria-label="Cargas preservadas nesta empresa" :value="savedId||''" @change="inspectLoad(Number($event.target.value))"><option disabled value="">Consultar uma carga importada</option><option v-for="l in loads" :key="l.id" :value="l.id">{{l.name}} · {{dateTime(l.created_at)}} · {{l.comparison.record_count}} registros</option></select></label>
<div class="table-toolbar"><input v-model="query" aria-label="Pesquisar registros da carga CFOP" placeholder="Código ou descrição da origem"/></div>
<div class="table-scroll"><table><thead><tr><th>Código da origem</th><th>Descrição preservada</th><th>Correspondência</th><th>Parâmetros</th></tr></thead><tbody><tr v-for="r in visible" :key="r.code"><td class="mono">{{r.code}}</td><td>{{r.source_description}}</td><td>{{r.match==='official'?'CFOP na referência':r.match==='legacy'?'Código de 3 dígitos · revisar':'Sem correspondência · revisar'}}</td><td><button class="text-button" @click="detail=r">Ver parâmetros {{r.code}}</button></td></tr></tbody></table></div><footer class="table-footer"><span>{{total}} registros · página {{page}} de {{pages}}</span><div class="actions"><button class="button small" :disabled="page===1||busy" @click="page--">Anterior</button><button class="button small" :disabled="page>=pages||busy" @click="page++">Próxima</button></div></footer>
<a v-if="savedId" class="button" :href="'/api'+scope(`/cfop-source-loads/${savedId}/original`)" download>Baixar carga preservada</a>
<BaseModal v-if="detail" :title="`Origem · código ${detail.code}`" @close="detail=null"><h3>{{detail.source_description}}</h3><p>Descrição do TXT: {{detail.txt_description}}</p><p v-if="detail.official_description">Descrição CONFAZ: {{detail.official_description}}</p><dl class="source-details source-fields"><template v-for="(value,key) in detail.parameters_declared" :key="key"><dt>{{labels[key]}}</dt><dd>{{value}}</dd></template><dt>Alíquotas informadas na origem</dt><dd>{{detail.rates_declared.length?detail.rates_declared.join(' · '):'Não informadas'}}</dd><dt>Vigência dos parâmetros</dt><dd>Não informada na origem</dd><dt>Aplicação automática</dt><dd>Desativada · parâmetros a revisar</dd></dl><template #footer><button class="button" @click="detail=null">Fechar</button></template></BaseModal>
</div></template>

<style scoped>
.cfop-source-panel{padding:16px;display:grid;gap:12px}.source-actions{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.cfop-source-panel p{margin:0;line-height:1.6}.cfop-source-panel .summary-strip{margin:0;padding:12px;border-radius:6px}.cfop-source-panel .table-toolbar{padding:0;border:0}.cfop-source-panel>button{justify-self:start}
.source-fields dt{min-width:0;max-width:100%;white-space:normal;overflow-wrap:anywhere}
</style>
